1	/**
2	 * The Angular holdout: compose the `@versionless/angular` changeset for the
3	 * pinned `angular-pigallery2-v1-7-0` tree and write it into a migrated lane, so
4	 * a closure can be installed into it and a production build attempted on the
5	 * bytes the frozen adapter produced.
6	 *
7	 * This application was never seen by the adapter while the adapter was being
8	 * designed. Nothing in `@versionless/angular` was written for it, and nothing in
9	 * `@versionless/angular` was changed for it: the adapter subtree is frozen at
10	 * tree oid ca3824d0595d1fa88d37feda6b1785dfd79e72c4 for the whole of this unit.
11	 * What this driver produces is therefore a measurement and not a demonstration.
12	 *
13	 * The driver is fixture-scoped. It knows three things about this application —
14	 * where its corpus was materialised, that its Angular `sourceRoot` is
15	 * `frontend/` rather than the conventional `src/`, and that the browser build's
16	 * compilation unit reaches into the sibling `common/` directory the backend also
17	 * compiles. Those are paths, read out of the application's own `angular.json`
18	 * and `tsconfig.app.json`. Every decision about *what to change* lives in the
19	 * frozen adapter, which knows nothing about this application.
20	 */
21	
22	import { readdir, readFile, mkdir, writeFile } from 'node:fs/promises';
23	import * as path from 'pathe';
24	import {
25		migrateAngularCliEraWorkspace,
26		ANGULAR_16_BROWSER_CELL,
27		type AngularMigration,
28		type WorkspaceFile,
29	} from '../../../frameworks/angular/src/index.ts';
30	import { canonical, sha256 } from './angular-factoriolab-migration-run.ts';
31	import { sealRecord, verifySealedRecord, type SealedRecord } from './angular-factoriolab-build-lanes-run.ts';
32	import { applyMigration, type Application } from './angular-tiny-translator-apply-run.ts';
33	
34	const repositoryRoot = path.resolve(import.meta.dirname, '../../../..');
35	
36	export const UNIT = 'lrapr-t018/u3-frozen-adapter-migration';
37	export const CONSENT = 'VL-LEGACY-CORPUS-2026-08-10';
38	export const COMMIT = '6d44c22df13b8f9416715e86e160707d0c3f973a';
39	
40	/** The immutable corpus the baseline lane was also cut from. */
41	export const SOURCE_TREE = path.join(
42		repositoryRoot,
43		'.versionless/cache/angular-pigallery2-v1-7-0-source/corpus',
44		`pigallery2-${COMMIT}`,
45	);
46	
47	/** The migrated lane, beside the baseline lane the previous unit built. */
48	export const STAGE_DIRECTORY = path.join(repositoryRoot, '.versionless/work/angular-pigallery2/target');
49	/** The pinned revision with the changeset written into it; the build tree. */
50	export const APPLIED_TREE = path.join(STAGE_DIRECTORY, 'app');
51	
52	export const EVIDENCE_DIRECTORY = path.join(
53		repositoryRoot,
54		'evidence/ingests/angular-pigallery2-v1-7-0/migration',
55	);
56	
57	export const CHANGESET_FILE = 'u3-composed-changeset.json';
58	export const MIGRATION_RECORD_FILE = 'u3-source-migration.json';
59	
60	/**
61	 * The two directories the Angular browser build compiles, and why the second one
62	 * is not the conventional single `sourceRoot`.
63	 *
64	 * `angular.json` declares `sourceRoot: "frontend"`, and `frontend/tsconfig.app.json`
65	 * includes `./**\/*` relative to it. TypeScript then follows the relative imports
66	 * the frontend modules write into `../common/`, so `common/**\/*.ts` is inside the
67	 * browser build's compilation unit even though no configuration file names it.
68	 * A migration handed only `frontend/` would scan a strict subset of what the
69	 * compiler reads.
70	 */
71	export const APPLICATION_SOURCE_DIRECTORIES: readonly string[] = Object.freeze(['frontend', 'common']);
72	
73	async function filesBelow(
74		directory: string,
75		root: string,
76		extension: string,
77	): Promise<WorkspaceFile[]> {
78		const files: WorkspaceFile[] = [];
79		for (const entry of (await readdir(directory, { withFileTypes: true })).sort((left, right) =>
80			left.name < right.name ? -1 : 1,
81		)) {
82			const item = path.join(directory, entry.name);
83			if (entry.isDirectory()) {
84				files.push(...(await filesBelow(item, root, extension)));
85				continue;
86			}
87			if (!entry.isFile() || path.extname(entry.name) !== extension) continue;
88			files.push({ path: path.relative(root, item), source: await readFile(item, 'utf8') });
89		}
90		return files;
91	}
92	
93	/** Every workspace-relative path the tree carries, excluding installed packages. */
94	async function workspacePathsBelow(directory: string, root: string): Promise<string[]> {
95		const paths: string[] = [];
96		for (const entry of (await readdir(directory, { withFileTypes: true })).sort((left, right) =>
97			left.name < right.name ? -1 : 1,
98		)) {
99			if (entry.name === 'node_modules' || entry.name === '.git') continue;
100			const item = path.join(directory, entry.name);
101			if (entry.isDirectory()) {
102				paths.push(...(await workspacePathsBelow(item, root)));
103				continue;
104			}
105			if (entry.isFile()) paths.push(path.relative(root, item));
106		}
107		return paths;
108	}
109	
110	async function collect(
111		tree: string,
112		extension: string,
113		directories: readonly string[],
114	): Promise<WorkspaceFile[]> {
115		const files: WorkspaceFile[] = [];
116		for (const directory of directories)
117			files.push(...(await filesBelow(path.join(tree, directory), tree, extension)));
118		return files;
119	}
120	
121	/**
122	 * Compose the changeset for the pinned tree.
123	 *
124	 * The workspace configuration handed in is a modern `angular.json`, so the
125	 * CLI 1.x synthesis capability stands down on its own — it reads the document's
126	 * shape, and nothing here tells it which format to expect.
127	 */
128	export async function composeMigration(tree: string): Promise<AngularMigration> {
129		const sourceModules = (await collect(tree, '.ts', APPLICATION_SOURCE_DIRECTORIES)).filter(
130			(module) => !module.path.endsWith('.spec.ts'),
131		);
132		return migrateAngularCliEraWorkspace(
133			{
134				packageManifest: {
135					path: 'package.json',
136					source: await readFile(path.join(tree, 'package.json'), 'utf8'),
137				},
138				workspaceConfig: {
139					path: 'angular.json',
140					source: await readFile(path.join(tree, 'angular.json'), 'utf8'),
141				},
142				tsConfig: {
143					path: 'tsconfig.json',
144					source: await readFile(path.join(tree, 'tsconfig.json'), 'utf8'),
145				},
146				sourceModules,
147				templates: await collect(tree, '.html', ['frontend']),
148				styleSheets: await collect(tree, '.css', ['frontend']),
149				workspaceFiles: await workspacePathsBelow(tree, tree),
150			},
151			ANGULAR_16_BROWSER_CELL,
152		);
153	}
154	
155	/**
156	 * Era workspace facts this application carries that the hop has to answer for or
157	 * declare dropped. They are named because a changeset that silently loses one of
158	 * them would still look clean.
159	 */
160	export const ERA_WORKSPACE_FACTS: readonly string[] = Object.freeze([
161		'`sourceRoot: "frontend"` and an `outputPath` of `dist` at the workspace root — this workspace is not `src/`-rooted, and its build output directory is the same one the backend release pipeline writes into.',
162		'`extractCss: true` on the production configuration — a valid key for the Angular 8 browser builder, and one the Angular 13 line removed.',
163		"The build is driven by the repository's own gulp task rather than by `ng` directly, and that task passes `--i18n-locale en --i18n-format=xlf --i18n-file=frontend/translate/messages.en.xlf --i18n-missing-translation warning`. Those are ViewEngine i18n flags of the Angular 8 CLI; the workspace file itself declares no i18n at all.",
164		'A second workspace project, pigallery2-e2e, whose only targets are the protractor e2e runner and a TSLint lint target.',
165		'The pigallery2 lint target names `src/tsconfig.app.json` and `src/tsconfig.spec.json` — paths that do not exist in this tree, because the workspace was renamed to `frontend/` without updating them. The era lint target was already broken at the pin.',
166		'`@angular/http@7.2.15` declared beside Angular 8.1.2 — a package Angular removed after the 7 line.',
167		'`rxjs-compat@6.5.2`, the RxJS 5-compatibility shim, declared beside rxjs 6.5.2.',
168	]);
169	
170	/** The changeset record: every file by path and by digest before and after. */
171	export function buildChangesetRecord(migration: AngularMigration): SealedRecord {
172		return sealRecord({
173			schemaVersion: 'versionless.angular-pigallery2-composed-changeset.v1',
174			unit: UNIT,
