		expect(toastr.buildStamp?.compiledWith).toBe('16.0.1');
		expect(toastr.excludedByBuildStamp?.map((stamp) => stamp.libraryVersion)).toEqual([
			'19.1.0',
			'19.0.0',
			'18.0.0',
		]);
